from pathlib import Path
import pandas as pd, pickle, json, os
root = Path('data')
files = sorted([p for p in root.rglob('*') if p.is_file()])
for p in files:
    suf = p.suffix.lower()
    print('\n===', p, '===')
    try:
        if suf == '.csv':
            df = pd.read_csv(p, nrows=5)
            print('CSV columns:', list(df.columns))
            print(df.head().to_string())
        elif suf == '.json':
            obj = json.loads(p.read_text()[:200000])
            if isinstance(obj, dict):
                print('JSON keys:', list(obj)[:30])
            else:
                print('JSON type:', type(obj), 'len=', len(obj))
        elif suf == '.pkl':
            with open(p, 'rb') as f:
                obj = pickle.load(f)
            print('PKL type:', type(obj))
            if hasattr(obj, 'keys'):
                print('keys:', list(obj.keys())[:40])
            elif hasattr(obj, 'shape'):
                print('shape:', obj.shape)
        elif suf in ('.h5', '.hdf5', '.nwb'):
            print('binary file; inspect later if needed')
        else:
            print('skipping detailed preview')
    except Exception as e:
        print('preview_error:', repr(e))
